from ntlib import sqrt_mod
from ecc import make_curve

for n in range(1, 151):
    for a in range(n):
        roots = [x for x in range(n) if (x * x - a) % n == 0]
        exists = bool(roots)
        try:
            r = sqrt_mod(a, n)
        except ValueError:
            if exists:
                raise AssertionError(f"sqrt_mod({a}, {n}) raised, but roots exist: {roots}")
        else:
            if not exists:
                raise AssertionError(f"sqrt_mod({a}, {n}) returned {r}, but no root exists")
            if (r * r - a) % n != 0:
                raise AssertionError(f"sqrt_mod({a}, {n}) = {r}, but r^2 != a")

print("exhaustive small-modulus tests passed")

curve = make_curve("test")
checked = 0
for x in range(curve.p):
    y_sq = (pow(x, 3, curve.p) + curve.a * x + curve.b) % curve.p
    for parity in (0, 1):
        roots = [y for y in range(curve.p) if (y * y - y_sq) % curve.p == 0]
        if not roots:
            continue
        px, py = curve.decompress_point(x, parity)
        assert py % 2 == parity
        assert curve.is_on_curve(px, py)
        checked += 1

print(f"ecc decompression tests passed ({checked} cases)")
